#include <pthread.h>

static atomic_bool init_done{false};

void init_thread() {
  // perform init
  atomic_store(&init_done, true, memory_order_release);
}

void wait_for_init() {
  while (!atomic_load(&init_done, memory_order_acquire)) {
    // spin or yield
  }
}
